package com.tracksphere.infrastructure.config; import io.swagger.v3.oas.models.*; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.security.*; import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig { @Bean OpenAPI trackSphereOpenApi(){return new OpenAPI().info(new Info().title("TrackSphere API").version("v1").description("Enterprise transportation tracking API")).addSecurityItem(new SecurityRequirement().addList("bearerAuth")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));} }
